function profileSummaryHtml(p){if(!p)return "";var name=p.nationality==="OTHER"?p.otherNationality:nationalityNames[p.nationality]||p.nationality;return '<div class="review-cell"><span>Nationality</span><strong>'+escapeHtml(name)+'</strong></div><div class="review-cell"><span>Current legal residence</span><strong>'+escapeHtml(p.residenceCountry==="OTHER"?(p.residenceOther||"Other country"):country(p.residenceCountry))+' · '+escapeHtml(p.residenceStatus)+'</strong></div><div class="review-cell"><span>Destination</span><strong>'+escapeHtml(p.destinationCity)+', '+escapeHtml(country(p.destinationCountry))+'</strong></div><div class="review-cell"><span>Travel dates</span><strong>'+escapeHtml(prettyDate(p.arrivalDate))+" – "+escapeHtml(prettyDate(p.departureDate))+'</strong></div><div class="review-cell"><span>Programme length</span><strong>'+escapeHtml(p.programmeLength)+'</strong><span>'+escapeHtml(durationDays(p.arrivalDate,p.departureDate))+' travel days</span></div><div class="review-cell"><span>Current visa / residence status</span><strong>'+escapeHtml(p.currentStatus)+'</strong></div>';}
function durationDays(start,end){if(!start||!end)return "Not calculated";var a=new Date(start+"T00:00:00"),b=new Date(end+"T00:00:00");var days=Math.round((b-a)/86400000);return days>0?String(days):"Check the dates";}
