function getSuggestedDocuments(){if(!state.profile)return [];var p=state.profile,stay=durationDays(p.arrivalDate,p.departureDate),place=p.destinationCity+", "+country(p.destinationCountry),items=[{id:"suggested-identity",title:"Valid passport or national identity card",help:"For your "+place+" trip, organize the identity document you plan to use and check its validity and accepted format with an official source."},{id:"suggested-study",title:"Admission or enrolment evidence",help:"Keep your host institution's acceptance, enrolment or exchange confirmation for "+place+" together."},{id:"suggested-housing",title:"Accommodation information",help:"Keep the address or booking details for "+place+" available; confirm whether formal proof is requested."},{id:"suggested-health",title:"Health coverage evidence",help:"Collect information about the health cover available for your "+stay+"-day stay and check the destination's current rules."},{id:"suggested-funds",title:"Financial support information",help:"Organize the records that explain how your study and stay will be funded; verify any required format or amount officially."}];var c=classification(p);if(c==="Non-EU citizen")items.push({id:"suggested-entry",title:"Entry or residence application documents",help:"Your "+c.toLowerCase()+" classification, current residence and "+stay+"-day stay can affect the route. Check current official instructions for the relevant form and supporting records."});else if(c==="EU citizen")items.push({id:"suggested-registration",title:"Local registration information",help:"Check whether the "+stay+"-day stay in "+place+" requires a local registration step and which information or form it uses."});return items;}
