function renderDocuments(){var list=el("suggestedDocuments"),extra=el("extraDocumentsList");if(!list||!extra)return;var items=getSuggestedDocuments();if(!state.profile){list.innerHTML='<div class="empty-state"><h2>Add your travel profile first</h2><p>Arrivio needs your nationality, legal residence, destination and trip dates to create its suggested list.</p><button class="button button-primary" type="button" data-route="profile">Complete travel profile</button></div>';}else{list.innerHTML=items.map(function(item){return documentCardHtml(item,false);}).join("");}extra.innerHTML=(state.extraDocuments||[]).length?state.extraDocuments.map(function(item){return documentCardHtml(item,true);}).join(""):'<p class="help-text">No extra documents added.</p>';el("documentListStatus").textContent=state.documentNeedsReview?"Review after profile change":state.documentsReviewed?"Saved on this device":"Not reviewed";}
