function renderTimeline(){var p=state.profile;el("timelineStatus").textContent=state.timelineReviewed?"Plan reviewed":"Needs review";if(!p){el("timelineTitle").textContent="Add your trip dates to build a timeline";el("timelineSummary").textContent="No deadlines will be shown unless you enter or verify them yourself.";el("timelineMilestones").innerHTML='<div class="empty-state" style="grid-column:1/-1"><h2>Your travel dates go here</h2><p>Start with the travel profile. Arrivio will organize your journey without inventing legal deadlines.</p><button class="button button-primary" type="button" data-route="profile">Add travel details</button></div>';return;}el("timelineTitle").textContent=p.destinationCity+", "+country(p.destinationCountry);el("timelineSummary").textContent=prettyDate(p.arrivalDate)+" to "+prettyDate(p.departureDate)+" · "+durationDays(p.arrivalDate,p.departureDate)+" travel days";var items=[{n:"01",title:"Profile confirmed",text:state.profileConfirmed?"Your details are saved.":"Review and confirm your details."},{n:"02",title:"Official information",text:state.sources.some(function(s){return s.verified&&!s.needsReview})?"A source record is saved.":state.sources.some(function(s){return s.needsReview})?"A saved source needs a fresh check.":"Check current official information."},{n:"03",title:"Before departure",text:"Use only verified dates and deadlines from official sources."},{n:"04",title:"After arrival",text:"Add local actions only when confirmed for your case."}];el("timelineMilestones").innerHTML=items.map(function(i){return '<div class="timeline-milestone"><span class="step-number">'+i.n+'</span><strong>'+escapeHtml(i.title)+'</strong><p>'+escapeHtml(i.text)+'</p></div>';}).join("");}
