function handleAction(action,target){if(action==="continue-later"){saveDraft();setRoute("home");notify("Your answers are saved on this device. Continue any time from Travel profile.");return;}if(action==="discard-draft"){state.profileDraft=null;persist();ArrivioProfileForm.clearAll();renderProfileForm();el("nationality").focus();notify("Unfinished answers discarded.");return;}if(action==="dismiss-saved-banner"){justConfirmed=false;renderSavedBanner();el("checklistDestination").focus();return;}if(action==="start-journey"){setRoute(state.profileConfirmed?"checklist":"profile");return;}if(action==="toggle-offline"){offlineDemo=!offlineDemo;updateConnection();if(offlineDemo)notify("Offline preview on. Changes remain on this device and are marked pending sync.");else notify("Connection preview restored. This demo still stores information only on this device.");return;}if(action==="clear-data"){if(window.confirm("Clear all Arrivio demo information saved in this browser? This cannot be undone.")){localStorage.removeItem(STORAGE_KEY);state=JSON.parse(JSON.stringify(defaults));selectedFile=null;el("identityFile").value="";el("selectedFileName").textContent="No file selected";setRoute("home");localStorage.removeItem(STORAGE_KEY);notify("Local demo data cleared.");}return;}if(action==="confirm-profile"){justConfirmed=true;state.profileConfirmed=true;state.checklistViewed=false;markTaskComplete("profile");persist();setRoute("checklist");/* Task 4: the persistent confirmation banner replaces the 3-second toast */return;}if(action==="continue-document"){if(!el("identityConsent").checked){notify("Confirm the optional demo notice before continuing.");el("identityConsent").focus();return;}if(!selectedFile){notify("Choose one file first, or enter details manually.");el("identityFile").focus();return;}state.identity.skipped=false;state.identity.manualStarted=true;state.identity.documentType=el("identityUploadType").value||"Passport";var nationality=state.profile?(state.profile.nationality==="OTHER"?state.profile.otherNationality:nationalityNames[state.profile.nationality]):"",issuer=state.profile?(state.profile.nationality==="OTHER"?state.profile.otherNationality:countryNames[state.profile.nationality]||nationalityNames[state.profile.nationality]):"";state.identity.review={name:"SAMPLE STUDENT",nationality:nationality,issuer:issuer,expiry:"2030-12-31"};persist();setRoute("identity-review");notify("Simulated read complete. Fictional sample values were filled in for review.");return;}if(action==="manual-entry"){state.identity.skipped=false;state.identity.manualStarted=true;selectedFile=null;el("identityFile").value="";el("selectedFileName").textContent="Manual entry selected. No file attached.";state.identity.documentType=el("identityUploadType").value||"Passport";state.identity.review={name:"",nationality:"",issuer:"",expiry:""};persist();setRoute("identity-review");return;}if(action==="skip-identity"){clearIdentity();state.identity.skipped=true;markTaskComplete("identity");markTaskComplete("review");persist();setRoute("checklist");notify("Identity document skipped. You can return to this optional step later.");return;}if(action==="delete-identity"){clearIdentity();state.identity.skipped=true;markTaskComplete("identity");markTaskComplete("review");persist();setRoute("checklist");notify("Identity details cleared. The optional step is skipped.");return;}if(action==="save-document-list"){if(!state.profileConfirmed){notify("Confirm your travel profile before saving the tailored document list.");setRoute("profile");return;}state.documentsReviewed=true;state.documentNeedsReview=false;markTaskComplete("documents");addActivity("Arrivio document suggestions reviewed",today(),"","Completed","documents");persist();render();notify("Suggested document list saved on this device.");return;}if(action==="download-draft"){if(!state.profile){notify("Complete your travel profile before creating the Word document.");setRoute("profile");return;}downloadPreparationDocx();state.draftPrepared=true;state.draftNeedsReview=false;markTaskComplete("draft");addActivity("Preparation document (.docx) downloaded",today(),".docx file","Completed","draft");persist();render();notify("Word preparation document downloaded. Nothing was submitted.");return;}if(action==="mark-draft-ready"){if(!state.draftPrepared){notify("Download the Word document before marking it reviewed.");return;}state.draftPrepared=true;state.draftNeedsReview=false;markTaskComplete("draft");addActivity("Preparation document reviewed",today(),"","Completed","draft");persist();render();notify("Word document marked as reviewed. It has not been submitted.");return;}if(action==="save-evidence"){var checks=currentEvidenceItems();if(!checks.length){notify("Complete your travel profile first.");return;}var all=checks.every(function(k){return state.evidenceChecks[k.id]});if(!all){notify("Review all suggested documents and the two preparation checks before marking ready.");return;}state.evidenceReady=true;state.evidenceNeedsReview=false;markTaskComplete("evidence");addActivity("Document readiness marked Ready for Submission",today(),"Readiness metadata only","Completed","evidence");persist();render();notify("Readiness recorded. You will submit through the official channel yourself.");return;}if(action==="reset-evidence"){state.evidenceChecks={};state.evidenceReady=false;state.evidenceNeedsReview=false;delete state.taskCompletedAt.evidence;persist();render();notify("Readiness checks reset.");return;}if(action==="open-booking"){var url=el("bookingUrl").value.trim();if(!validHttps(url)){notify("Add a secure HTTPS booking page first.");return;}window.open(url,"_blank","noopener,noreferrer");return;}if(action==="confirm-timeline"){state.timelineReviewed=true;markTaskComplete("timeline");addActivity("Travel timeline reviewed",today(),"","Completed","timeline");persist();render();notify("Timeline review saved.");return;}if(action==="filter-all"){filterMode="all";renderChecklist();return;}if(action==="filter-todo"){filterMode="todo";renderChecklist();return;}if(action==="filter-focus"){filterMode="focus";renderChecklist();return;}if(action==="apply-profile-change"){applyProfileChange();return;}if(action==="cancel-profile-change"){pendingProfile=null;el("timelineDialog").close();notify("Current travel plan kept.");return;}if(action==="close-dialog"){el("timelineDialog").close();pendingProfile=null;return;}if(action==="close-activity-dialog"){el("editActivityDialog").close();return;}}
function onDocumentClick(ev){var routeButton=ev.target.closest("[data-route]");if(routeButton){ev.preventDefault();setRoute(routeButton.getAttribute("data-route"));return;}var taskButton=ev.target.closest("[data-open-task]");if(taskButton){setRoute(taskButton.getAttribute("data-open-task"));return;}var actionButton=ev.target.closest("[data-action]");if(actionButton){handleAction(actionButton.getAttribute("data-action"),actionButton);return;}var edit=ev.target.closest("[data-edit-activity]");if(edit){openActivityEdit(edit.getAttribute("data-edit-activity"));return;}var undo=ev.target.closest("[data-undo-activity]");if(undo){undoActivity(undo.getAttribute("data-undo-activity"));return;}var removeDoc=ev.target.closest("[data-remove-document]");if(removeDoc){var id=removeDoc.getAttribute("data-remove-document");state.extraDocuments=state.extraDocuments.filter(function(d){return d.id!==id});delete state.documentChecks[id];state.documentsReviewed=false;state.documentNeedsReview=false;persist();renderDocuments();renderChecklist();notify("Additional document removed.");return;}var remove=ev.target.closest("[data-remove-source]");if(remove){state.sources=state.sources.filter(function(src){return src.id!==remove.getAttribute("data-remove-source")});persist();renderSources();renderChecklist();notify("Source record removed.");}}
function openActivityEdit(id){var a=state.activity.find(function(x){return x.id===id&&!x.undone});if(!a)return;el("editActivityId").value=a.id;el("editActivityName").value=a.title;el("editActivityDate").value=a.date;el("editActivityStatus").value=a.status;el("editActivityReference").value=a.reference;el("editActivityDialog").showModal();}
function undoActivity(id){var a=state.activity.find(function(x){return x.id===id&&!x.undone});if(!a)return;if(!window.confirm("Undo this activity record? You can add it again later."))return;a.undone=true;if(a.effect==="draft"){state.draftPrepared=false;delete state.taskCompletedAt.draft;}if(a.effect==="evidence"){state.evidenceReady=false;delete state.taskCompletedAt.evidence;}if(a.effect==="documents"){state.documentsReviewed=false;delete state.taskCompletedAt.documents;}if(a.effect==="identity"){clearIdentity();delete state.taskCompletedAt.identity;delete state.taskCompletedAt.review;}if(a.effect==="appointment"){state.appointment.date="";state.appointment.reference="";if(state.appointment.need==="yes")state.appointment.need="";delete state.taskCompletedAt.appointment;}if(a.effect==="timeline"){state.timelineReviewed=false;delete state.taskCompletedAt.timeline;}if(a.effect==="manual"){var remaining=state.activity.filter(function(x){return !x.undone&&x.status==="Completed"});if(remaining.length)markTaskComplete("activity",remaining[0].date);else delete state.taskCompletedAt.activity;}persist();render();notify("Activity record undone.");}
